import os
from datetime import datetime
from flask import Flask, request, Response
import psycopg2
from psycopg2.extras import RealDictCursor

app = Flask(__name__)
DB_URL = os.environ["SUPABASE_DB_URL"]

def get_conn():
    return psycopg2.connect(DB_URL, cursor_factory=RealDictCursor)

KEYWORDS_HELP = {"help", "resource", "need"}
KEYWORDS_OK = {"here", "ok", "done", "good", "in"}

def get_or_create_user(conn, phone):
    cur = conn.cursor()
    cur.execute("SELECT * FROM app_user WHERE phone=%s", (phone,))
    user = cur.fetchone()
    if not user:
        cur.execute(
            "INSERT INTO app_user (phone) VALUES (%s) RETURNING *", (phone,)
        )
        user = cur.fetchone()
        conn.commit()
    return user

def record_checkin(conn, user, status, note):
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO check_in (user_id, status, note) VALUES (%s,%s,%s)",
        (user["id"], status, note),
    )
    if status == "on_time":
        cur.execute(
            "UPDATE app_user SET streak_count = streak_count + 1 WHERE id=%s",
            (user["id"],),
        )
    else:
        cur.execute(
            "UPDATE app_user SET streak_count = 0 WHERE id=%s", (user["id"],)
        )
    conn.commit()

def classify_message(body: str) -> str:
    text = body.strip().lower()
    if any(k in text for k in KEYWORDS_HELP):
        return "needs_help"
    if any(k in text for k in KEYWORDS_OK):
        return "on_time"
    return "missed"

@app.route("/sms", methods=["POST"])
def sms_webhook():
    from_number = request.form.get("From", "")
    body = request.form.get("Body", "")
    conn = get_conn()
    user = get_or_create_user(conn, from_number)
    status = classify_message(body)
    record_checkin(conn, user, status, body)

    if status == "needs_help":
        reply = (
            "Got it. Reply with your zip code and what you need "
            "(housing, job, ID, food, legal) and we'll text you real resources."
        )
    elif status == "on_time":
        streak = user["streak_count"] + 1
        reply = f"Logged. Streak: {streak} days. Keep going, you got this."
    else:
        reply = "Missed check-in logged. Text HELP if you need resources. No judgment, just text back when you can."

    twiml = f"<Response><Message>{reply}</Message></Response>"
    return Response(twiml, mimetype="text/xml")

@app.route("/health", methods=["GET"])
def health():
    return {"status": "ok", "time": datetime.utcnow().isoformat()}

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", 5000)))
